CREATE TABLE `fw_job` ( `id` varchar(36) NOT NULL PRIMARY KEY, `kind` varchar(128) NOT NULL, `module` varchar(64) NOT NULL, `status` varchar(16) NOT NULL, `payload` text NOT NULL, `priority` int NOT NULL, `attempts` int NOT NULL, `max_attempts` int NOT NULL, `retry_safe` bool NOT NULL, `cancel_requested` bool NOT NULL, `run_after` bigint NOT NULL, `created_at` bigint NOT NULL, `updated_at` bigint NOT NULL, `row_version` bigint NOT NULL, `lease_expires_at` bigint, `progress_current` bigint, `progress_total` bigint, `started_at` bigint, `finished_at` bigint, `lease_owner` varchar(64), `progress_message` varchar(128), `error_code` varchar(128), `submitted_by` varchar(36), `progress_params` text, `result` text, `error_params` text ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX `ix_fw_job_queue` ON `fw_job` (`status`, `run_after`, `priority`);
CREATE INDEX `ix_fw_job_kind` ON `fw_job` (`kind`);
CREATE INDEX `ix_fw_job_created_at` ON `fw_job` (`created_at`);
